/* HEXA BATTLEGROUNDS setup — PART 62 OF 84. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-bomb-12', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Black, White, Blue, Yellow.\nSerial number: OM67Z8.  LED: BLUE.","game":{"type":"bomb","wires":["green","black","white","blue","yellow"],"serial":"OM67Z8","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,black,white,blue,yellow · OM67Z8 · blue → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-bomb-13', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Red, Red, Blue, White, White.\nSerial number: TN38A0.  LED: BLUE.","game":{"type":"bomb","wires":["red","red","blue","white","white"],"serial":"TN38A0","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'red,red,blue,white,white · TN38A0 · blue → more than one red → last red → wire 2', null, 25, 'published'), ('mission-bomb-14', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Red, White, Yellow, Red, Red.\nSerial number: HX57Z2.  LED: BLUE.","game":{"type":"bomb","wires":["red","white","yellow","red","red"],"serial":"HX57Z2","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["5"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'red,white,yellow,red,red · HX57Z2 · blue → more than one red → last red → wire 5', null, 25, 'published'), ('mission-bomb-15', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, Yellow, Red, Black.\nSerial number: SR12Z7.  LED: BLUE.","game":{"type":"bomb","wires":["blue","yellow","red","black"],"serial":"SR12Z7","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,yellow,red,black · SR12Z7 · blue → serial ends odd and there is blue → first blue → wire 1', null, 25, 'published'), ('mission-bomb-16', 'bomb', 'mission', 'Bomb Defusal', 'game', 1, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, White, Red, Blue, Green, Yellow.\nSerial number: SR59K8.  LED: BLUE.","game":{"type":"bomb","wires":["black","white","red","blue","green","yellow"],"serial":"SR59K8","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,white,red,blue,green,yellow · SR59K8 · blue → otherwise → first wire → wire 1', null, 25, 'published'), ('mission-bomb-17', 'bomb', 'mission', 'Bomb Defusal', 'game', 2, array['access','testing','office','phase2','glass','observation','any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Red, Yellow, Blue, Yellow.\nSerial number: OM74Z4.  LED: RED.","game":{"type":"bomb","wires":["green","red","yellow","blue","yellow"],"serial":"OM74Z4","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 200, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,red,yellow,blue,yellow · OM74Z4 · red → otherwise → first wire → wire 1', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
